using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Hydris.Generators;

[Generator]
public sealed class ServiceGenerator : IIncrementalGenerator {
    private static readonly SymbolDisplayFormat FullyQualified = SymbolDisplayFormat.FullyQualifiedFormat;

    private const string RendererSource =
        """
        // <auto-generated/>
        #nullable enable
        namespace Hydris.Generated;

        internal static class GeneratedRenderer
        {
            [global::System.Runtime.CompilerServices.ModuleInitializer]
            internal static void Initialize()
            {
                global::Hydris.Bootstrap.RegisterServices(static c => c.Singleton<global::Hydris.Renderer.IRenderer>(static _ => new global::Hydris.QuickJs.QuickJsRenderer()));
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context) {
        context.RegisterPostInitializationOutput(static ctx => ctx.AddSource("GeneratedBootstrap.g.cs",
            """
            // <auto-generated/>
            #nullable enable
            namespace Hydris.Generated;

            internal static class GeneratedBootstrap
            {
                [global::System.Runtime.CompilerServices.ModuleInitializer]
                internal static void Initialize()
                {
                    global::Hydris.Bootstrap.RegisterServices(static c => global::Hydris.Container.GeneratedServices.AddServices(c));
                    global::Hydris.Bootstrap.RegisterRoutes(static r => global::Hydris.Routing.GeneratedRoutes.MapRoutes(r));
                }
            }
            """));

        var hasQuickJs = context.CompilationProvider.Select(static (compilation, _) =>
            compilation.GetTypeByMetadataName("Hydris.QuickJs.QuickJsRenderer") is not null);

        context.RegisterSourceOutput(hasQuickJs, static (production, present) => {
            if (present)
                production.AddSource("GeneratedRenderer.g.cs", RendererSource);
        });

        var singletons = Registrations(context, "Hydris.Container.SingletonAttribute", "Singleton");
        var scoped = Registrations(context, "Hydris.Container.ScopedAttribute", "Scoped");
        var transient = Registrations(context, "Hydris.Container.TransientAttribute", "Transient");
        var handlers = Registrations(context, "Hydris.Container.HandlerAttribute", "Scoped");
        var middlewares = Registrations(context, "Hydris.Middleware.MiddlewareAttribute", "Scoped");
        var configs = Registrations(context, "Hydris.Container.ConfigAttribute", "Singleton");

        var combined = singletons.Collect()
            .Combine(scoped.Collect())
            .Combine(transient.Collect())
            .Combine(handlers.Collect())
            .Combine(middlewares.Collect())
            .Combine(configs.Collect());

        context.RegisterSourceOutput(combined, static (production, data) => {
            var (((((singleton, scope), transientLines), handlerLines), middlewareLines), configLines) = data;
            var lines = new List<string>();
            Collect(lines, singleton);
            Collect(lines, scope);
            Collect(lines, transientLines);
            Collect(lines, handlerLines);
            Collect(lines, middlewareLines);
            Collect(lines, configLines);
            production.AddSource("GeneratedServices.g.cs", Emit(lines));
        });

        var routeGet = RouteRegistrations(context, "Hydris.Routing.GetAttribute", "Get");
        var routePost = RouteRegistrations(context, "Hydris.Routing.PostAttribute", "Post");
        var routePut = RouteRegistrations(context, "Hydris.Routing.PutAttribute", "Put");
        var routePatch = RouteRegistrations(context, "Hydris.Routing.PatchAttribute", "Patch");
        var routeDelete = RouteRegistrations(context, "Hydris.Routing.DeleteAttribute", "Delete");

        var routes = routeGet.Collect()
            .Combine(routePost.Collect())
            .Combine(routePut.Collect())
            .Combine(routePatch.Collect())
            .Combine(routeDelete.Collect());

        context.RegisterSourceOutput(routes, static (production, data) => {
            var ((((get, post), put), patch), delete) = data;
            var lines = new List<string>();
            Collect(lines, get);
            Collect(lines, post);
            Collect(lines, put);
            Collect(lines, patch);
            Collect(lines, delete);
            production.AddSource("GeneratedRoutes.g.cs", EmitRoutes(lines));
        });
    }

    private static IncrementalValuesProvider<string?> RouteRegistrations(
        IncrementalGeneratorInitializationContext context,
        string attribute,
        string httpMethod) {
        return context.SyntaxProvider.ForAttributeWithMetadataName(
            attribute,
            static (node, _) => node is MethodDeclarationSyntax,
            (syntax, _) => RouteRegistration(syntax, httpMethod));
    }

    private static string? RouteRegistration(GeneratorAttributeSyntaxContext syntax, string httpMethod) {
        if (syntax.TargetSymbol is not IMethodSymbol method)
            return null;
        if (syntax.Attributes.Length == 0)
            return null;

        var arguments = syntax.Attributes[0].ConstructorArguments;
        if (arguments.Length == 0 || arguments[0].Value is not string path)
            return null;

        var controller = method.ContainingType.ToDisplayString(FullyQualified);
        var literal = "\"" + path.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

        var uses = new List<string>();
        CollectUse(method.ContainingType.GetAttributes(), uses);
        CollectUse(method.GetAttributes(), uses);
        var chain = "[" + string.Join(", ", uses) + "]";

        var noCsrf = HasNoCsrf(method.ContainingType.GetAttributes()) || HasNoCsrf(method.GetAttributes())
            ? "true"
            : "false";

        if (HasAction(method.GetAttributes()) || method.Parameters.Length > 0)
            return EmitBoundRoute(method, httpMethod, literal, path, chain, noCsrf);

        var json = HasJson(method.ContainingType.GetAttributes()) || HasJson(method.GetAttributes())
            ? "true"
            : "false";

        return $"router.Map<{controller}>(global::Hydris.Routing.Method.{httpMethod}, {literal}, {chain}, {json}, {noCsrf}, static c => c.{method.Name}());";
    }

    private static bool HasAction(ImmutableArray<AttributeData> attributes) {
        foreach (var attribute in attributes) {
            if (attribute.AttributeClass?.ToDisplayString() == "Hydris.Routing.ActionAttribute")
                return true;
        }

        return false;
    }

    private static string EmitBoundRoute(IMethodSymbol method, string httpMethod, string literal, string path, string chain, string noCsrf) {
        var controller = method.ContainingType.ToDisplayString(FullyQualified);
        var awaitable = method.ReturnType is INamedTypeSymbol named
            && named.TypeArguments.Length == 1
            && (named.Name == "Task" || named.Name == "ValueTask")
            && named.ContainingNamespace?.ToDisplayString() == "System.Threading.Tasks";
        var resultType = awaitable
            ? ((INamedTypeSymbol)method.ReturnType).TypeArguments[0].ToDisplayString(FullyQualified)
            : method.ReturnType.ToDisplayString(FullyQualified);
        var call = awaitable ? "await handler." : "handler.";

        var routeParams = RouteParamNames(path);
        var hasBody = method.Parameters.Any(p => IsContract(p.Type));
        var async = awaitable || hasBody;
        var needsRequest = method.Parameters.Length > 0;

        var builder = new StringBuilder();
        builder.Append("router.Map(global::Hydris.Routing.Method.").Append(httpMethod).Append(", ").Append(literal).Append(", ").Append(chain).Append(", true, ").Append(noCsrf).Append(", ");
        builder.Append(async ? "static async scope => { " : "static scope => { ");
        builder.Append("var handler = scope.Get<").Append(controller).Append(">(); ");
        if (needsRequest)
            builder.Append("var request = scope.Get<global::Hydris.Http.Request>(); ");
        if (needsRequest)
            builder.Append("var errors = new global::Hydris.Contracts.ContractValidation(); ");

        var args = new List<string>();
        foreach (var parameter in method.Parameters) {
            var arg = "__arg_" + parameter.Name;
            var type = parameter.Type.ToDisplayString(FullyQualified);
            if (IsContract(parameter.Type)) {
                builder.Append("byte[] __body = await request.ReadBodyAsync(); ");
                builder.Append(type).Append("? ").Append(arg).Append(" = ").Append(type).Append(".Parse(__body, errors); ");
                builder.Append("if (").Append(arg).Append(" is null) return errors.ToReply(); ");
            } else {
                var route = routeParams.Contains(parameter.Name);
                var source = route
                    ? $"request.Param(\"{parameter.Name}\")"
                    : $"request.QueryValue(\"{parameter.Name}\")";
                var nullable = UnwrapNullable(parameter.Type) is not null
                    || parameter.NullableAnnotation == NullableAnnotation.Annotated;
                EmitScalarBind(builder, arg, parameter.Type, source, parameter.Name, route || !nullable);
            }

            args.Add(arg);
        }

        if (needsRequest)
            builder.Append("if (errors.Failed) ").Append(Return("errors.ToReply()", async)).Append(' ');
        builder.Append(resultType).Append(" result = ").Append(call).Append(method.Name).Append('(').Append(string.Join(", ", args)).Append("); ");
        builder.Append(Return("result", async)).Append(" });");

        return builder.ToString();
    }

    private static string Return(string expr, bool async) =>
        async ? "return " + expr + ";" : "return global::System.Threading.Tasks.Task.FromResult(" + expr + ");";

    private static void EmitScalarBind(StringBuilder builder, string arg, ITypeSymbol type, string source, string name, bool required) {
        var full = type.ToDisplayString(FullyQualified);
        var underlying = UnwrapNullable(type);
        var core = underlying ?? type;

        if (core.SpecialType == SpecialType.System_String) {
            if (required)
                builder.Append("string ").Append(arg).Append(" = ").Append(source).Append(" ?? string.Empty; ");
            else
                builder.Append("string? ").Append(arg).Append(" = ").Append(source).Append("; ");
            return;
        }

        var parse = TryParseExpr(core);
        builder.Append(full).Append(' ').Append(arg).Append(" = default; ");
        if (parse is null)
            return;
        builder.Append("{ var __raw = ").Append(source).Append("; if (__raw is null) { ");
        if (required)
            builder.Append("errors.Add(\"").Append(name).Append("\", \"required\", \"").Append(name).Append(" is required.\"); ");
        builder.Append("} else if (").Append(parse).Append("(__raw, out var __v)) { ").Append(arg).Append(" = __v; } else { ");
        builder.Append("errors.Add(\"").Append(name).Append("\", \"invalid\", \"").Append(name).Append(" is invalid.\"); } } ");
    }

    private static string? TryParseExpr(ITypeSymbol type) {
        if (type.TypeKind == TypeKind.Enum)
            return "global::System.Enum.TryParse<" + type.ToDisplayString(FullyQualified) + ">";
        var full = type.ToDisplayString(FullyQualified);
        return type.SpecialType switch {
            SpecialType.System_Int32 => "int.TryParse",
            SpecialType.System_Int64 => "long.TryParse",
            SpecialType.System_Int16 => "short.TryParse",
            SpecialType.System_Byte => "byte.TryParse",
            SpecialType.System_SByte => "sbyte.TryParse",
            SpecialType.System_UInt16 => "ushort.TryParse",
            SpecialType.System_UInt32 => "uint.TryParse",
            SpecialType.System_UInt64 => "ulong.TryParse",
            SpecialType.System_Single => "float.TryParse",
            SpecialType.System_Double => "double.TryParse",
            SpecialType.System_Decimal => "decimal.TryParse",
            SpecialType.System_Boolean => "bool.TryParse",
            _ => full switch {
                "global::System.Guid" => "global::System.Guid.TryParse",
                "global::System.DateTime" => "global::System.DateTime.TryParse",
                "global::System.DateTimeOffset" => "global::System.DateTimeOffset.TryParse",
                _ => null,
            },
        };
    }

    private static ITypeSymbol? UnwrapNullable(ITypeSymbol type) =>
        type is INamedTypeSymbol named && named.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T
            ? named.TypeArguments[0]
            : null;

    private static bool IsContract(ITypeSymbol type) =>
        type.GetAttributes().Any(static a => a.AttributeClass?.ToDisplayString() == "Hydris.Contracts.ContractAttribute");

    private static HashSet<string> RouteParamNames(string path) {
        var names = new HashSet<string>(System.StringComparer.Ordinal);
        foreach (var segment in path.Split('/')) {
            if (segment.Length > 1 && segment[0] == ':')
                names.Add(segment.Substring(1));
        }

        return names;
    }

    private static void CollectUse(ImmutableArray<AttributeData> attributes, List<string> into) {
        foreach (var attribute in attributes) {
            var attributeClass = attribute.AttributeClass;
            if (attributeClass is null || attributeClass.TypeArguments.Length != 1)
                continue;
            var definition = attributeClass.OriginalDefinition;
            if (definition.Name != "MiddlewareAttribute"
                || definition.ContainingNamespace?.ToDisplayString() != "Hydris.Middleware")
                continue;
            into.Add($"typeof({attributeClass.TypeArguments[0].ToDisplayString(FullyQualified)})");
        }
    }

    private static bool HasJson(ImmutableArray<AttributeData> attributes) {
        foreach (var attribute in attributes) {
            if (attribute.AttributeClass?.ToDisplayString() == "Hydris.Http.JsonAttribute")
                return true;
        }

        return false;
    }

    private static bool HasNoCsrf(ImmutableArray<AttributeData> attributes) {
        foreach (var attribute in attributes) {
            if (attribute.AttributeClass?.ToDisplayString() == "Hydris.Http.NoCsrfAttribute")
                return true;
        }

        return false;
    }

    private static string EmitRoutes(List<string> lines) {
        var builder = new StringBuilder();
        builder.AppendLine("// <auto-generated/>");
        builder.AppendLine("#nullable enable");
        builder.AppendLine("namespace Hydris.Routing;");
        builder.AppendLine();
        builder.AppendLine("public static class GeneratedRoutes");
        builder.AppendLine("{");
        builder.AppendLine("    public static Router MapRoutes(this Router router)");
        builder.AppendLine("    {");
        foreach (var line in lines)
            builder.Append("        ").AppendLine(line);
        builder.AppendLine("        return router;");
        builder.AppendLine("    }");
        builder.AppendLine("}");
        return builder.ToString();
    }

    private static IncrementalValuesProvider<string?> Registrations(
        IncrementalGeneratorInitializationContext context,
        string attribute,
        string lifetime) {
        return context.SyntaxProvider.ForAttributeWithMetadataName(
            attribute,
            static (node, _) => node is TypeDeclarationSyntax,
            (syntax, _) => Registration(syntax, lifetime));
    }

    private static string? Registration(GeneratorAttributeSyntaxContext syntax, string lifetime) {
        if (syntax.TargetSymbol is not INamedTypeSymbol type)
            return null;

        var constructor = type.InstanceConstructors
            .Where(candidate => candidate.DeclaredAccessibility == Accessibility.Public)
            .OrderByDescending(candidate => candidate.Parameters.Length)
            .FirstOrDefault();
        if (constructor is null)
            return null;

        var typeName = type.ToDisplayString(FullyQualified);
        var arguments = string.Join(
            ", ",
            constructor.Parameters.Select(parameter => $"r.Get<{parameter.Type.ToDisplayString(FullyQualified)}>()"));

        return $"container.{lifetime}(static r => new {typeName}({arguments}));";
    }

    private static void Collect(List<string> lines, ImmutableArray<string?> registrations) {
        foreach (var registration in registrations) {
            if (registration is not null)
                lines.Add(registration);
        }
    }

    private static string Emit(List<string> lines) {
        var builder = new StringBuilder();
        builder.AppendLine("// <auto-generated/>");
        builder.AppendLine("#nullable enable");
        builder.AppendLine("namespace Hydris.Container;");
        builder.AppendLine();
        builder.AppendLine("public static class GeneratedServices");
        builder.AppendLine("{");
        builder.AppendLine("    public static DiContainer AddServices(this DiContainer container)");
        builder.AppendLine("    {");
        foreach (var line in lines)
            builder.Append("        ").AppendLine(line);
        builder.AppendLine("        return container;");
        builder.AppendLine("    }");
        builder.AppendLine("}");
        return builder.ToString();
    }
}
